// Delivered goods remain buyer-owned inventory until the next consumption pass.
// Food keeps its existing warehouse and ledger for save compatibility.
const {add,number}=require('./autonomous-economy.cjs');
function enable(e){if(e.trade?.routing&&!e.trade.consumerStocks)e.trade.consumerStocks=e.households.map(h=>({householdId:h.id,inventories:[...new Set(e.rules.consumerNeeds.filter(n=>n.goodId!==e.rules.foodGoodId).map(n=>n.goodId))].sort().map(goodId=>({goodId,quantity:0,bookValueMinor:0}))}));}
function context(e){const at=new Map((e.trade?.householdStocks||[]).map(s=>[s.householdId,new Map([[e.rules.foodGoodId,s]])]));for(const row of e.trade?.consumerStocks||[]){if(!at.has(row.householdId))at.set(row.householdId,new Map());for(const s of row.inventories)at.get(row.householdId).set(s.goodId,s);}return at;}
function stock(e,id,good,at=context(e)){return at.get(id)?.get(good);}
function ownership(e,population){if(!e?.trade||!e.householdEconomy)return;const counts=new Map();for(const c of population.cohorts){if(!counts.has(c.territoryId))counts.set(c.territoryId,{rural:0,urban:0});const p=counts.get(c.territoryId);p[c.settlement]=add(p[c.settlement],c.count);}const at=context(e);for(const h of e.households){const p=counts.get(h.provinceId)||{rural:0,urban:0},total=add(p.rural,p.urban);for(const s of at.get(h.id)?.values()||[])if(!Object.hasOwn(s,'ruralQuantity')){s.ruralQuantity=total?number(BigInt(s.quantity)*BigInt(p.rural)/BigInt(total)):s.quantity;s.ruralBookValueMinor=s.quantity?number(BigInt(s.bookValueMinor)*BigInt(s.ruralQuantity)/BigInt(s.quantity)):0;}}const houses=new Map(e.households.map(h=>[h.id,h]));for(const c of e.trade.routing?.cargo||[])if(houses.has(c.ownerId)&&c.purpose!=='production'&&!Object.hasOwn(c,'sector'))c.sector=counts.get(houses.get(c.ownerId).provinceId)?.urban?'urban':'rural';}
function validateOwnership(s){if(!Object.hasOwn(s,'ruralQuantity'))return;const safe=n=>Number.isSafeInteger(n)&&n>=0;if(!safe(s.ruralQuantity)||!safe(s.ruralBookValueMinor)||s.ruralQuantity>s.quantity||s.ruralBookValueMinor>s.bookValueMinor||!s.ruralQuantity&&s.ruralBookValueMinor||s.ruralQuantity===s.quantity&&s.ruralBookValueMinor!==s.bookValueMinor)throw Error('Consumer deliveries: invalid sector ownership');}
function takeSector(s,quantity,sector){if(!Object.hasOwn(s,'ruralQuantity'))return require('./economy-trade.cjs').take(s,quantity);const rural=sector==='rural',held=rural?s.ruralQuantity:s.quantity-s.ruralQuantity,book=rural?s.ruralBookValueMinor:s.bookValueMinor-s.ruralBookValueMinor;if(quantity>held)throw Error('Consumer deliveries: insufficient sector stock');const value=quantity?number(BigInt(book)*BigInt(quantity)/BigInt(held)):0;s.quantity-=quantity;s.bookValueMinor-=value;if(rural){s.ruralQuantity-=quantity;s.ruralBookValueMinor-=value;}return value;}
function validate(e){if(!e.trade||!Object.hasOwn(e.trade,'consumerStocks'))return;if(!Array.isArray(e.trade.consumerStocks))throw Error('Consumer deliveries: invalid warehouses');const ids=new Set(e.households.map(h=>h.id)),goods=new Set(e.rules.consumerNeeds.filter(n=>n.goodId!==e.rules.foodGoodId).map(n=>n.goodId)),seen=new Set(),safe=n=>Number.isSafeInteger(n)&&n>=0;for(const row of e.trade.consumerStocks){if(Object.keys(row).length!==2||!Array.isArray(row.inventories)||!ids.has(row.householdId)||seen.has(row.householdId))throw Error('Consumer deliveries: invalid owner');seen.add(row.householdId);const held=new Set();for(const s of row.inventories){if(Object.keys(s).length!==(Object.hasOwn(s,'ruralQuantity')?5:3)||!goods.has(s.goodId)||held.has(s.goodId)||!safe(s.quantity)||!safe(s.bookValueMinor)||!s.quantity&&s.bookValueMinor)throw Error('Consumer deliveries: invalid stock');validateOwnership(s);held.add(s.goodId);}if(held.size!==goods.size)throw Error('Consumer deliveries: missing goods');}if(seen.size!==ids.size)throw Error('Consumer deliveries: missing owner');}
function pending(e,h,good,arrivals,at){return add(stock(e,h.id,good,at)?.quantity||0,require('./economy-routes.cjs').incoming(e,h.id,good,arrivals));}
function incomingSector(e,id,good,sector,arrivals){const rows=arrivals?(arrivals.get(id)?.get(good)||[]):e.trade?.routing?.cargo.filter(c=>c.ownerId===id&&c.goodId===good)||[];return rows.filter(c=>(c.sector||'urban')===sector).reduce((n,c)=>add(n,c.quantity),0);}
function demands(e,h,arrivals,at=context(e)){
  const grouped=new Map();for(const n of e.rules.consumerNeeds){if(n.goodId===e.rules.foodGoodId)continue;const state=h.consumerState.find(s=>s.needId===n.id);if(!grouped.has(n.goodId))grouped.set(n.goodId,{goodId:n.goodId,needState:state,usage:n.usage,quantity:0,ruralNeed:0,urbanNeed:0,priority:n.priority});const row=grouped.get(n.goodId);row.quantity=add(row.quantity,state.stats.unmetNeed);if(state.sectors)for(const sector of ['rural','urban'])row[sector+'Need']=add(row[sector+'Need'],state.sectors[sector+'Need']-state.sectors[sector+'Purchased']);}
  for(const d of grouped.values()){if(h.accounts){const s=stock(e,h.id,d.goodId,at);d.ruralNeed=Math.max(0,d.ruralNeed-(s?.ruralQuantity||0)-incomingSector(e,h.id,d.goodId,'rural',arrivals));d.urbanNeed=Math.max(0,d.urbanNeed-((s?.quantity||0)-(s?.ruralQuantity||0))-incomingSector(e,h.id,d.goodId,'urban',arrivals));d.quantity=add(d.ruralNeed,d.urbanNeed);}else d.quantity=Math.max(0,d.quantity-pending(e,h,d.goodId,arrivals,at));}return [...grouped.values()];
}
function opening(e,h,people,ruralPeople,arrivals,at,householdRow){
  const rows=[],targets=new Map(),available=new Map();let own=householdRow?.inventories.find(s=>s.goodId===e.rules.foodGoodId)?.quantity||0;
  for(const n of e.rules.consumerNeeds){const state=h.consumerState.find(s=>s.needId===n.id),target=number((BigInt(people)*BigInt(n.perPersonNumerator)+BigInt(n.usage==='consumable'?state.remainder:0))/BigInt(n.perPersonDenominator)),held=h.inUse.find(s=>s.goodId===n.goodId)?.quantity||0,need=n.usage==='durable'?Math.max(0,target-Math.max(held,targets.get(n.goodId)||0)):target;if(n.usage==='durable')targets.set(n.goodId,Math.max(targets.get(n.goodId)||0,target));
    if(!available.has(n.goodId)){const s=stock(e,h.id,n.goodId,at);available.set(n.goodId,{pooled:pending(e,h,n.goodId,arrivals,at),rural:add(s?.ruralQuantity||0,incomingSector(e,h.id,n.goodId,'rural',arrivals)),urban:add((s?.quantity||0)-(s?.ruralQuantity||0),incomingSector(e,h.id,n.goodId,'urban',arrivals))});}
    const a=available.get(n.goodId),rural=number(BigInt(need)*BigInt(ruralPeople)/BigInt(Math.max(1,people))),natural=n.goodId===e.rules.foodGoodId&&n.usage==='consumable'?Math.min(own,rural):0;own-=natural;let ruralPaid=0,urbanPaid=0;
    if(h.accounts){ruralPaid=Math.min(rural-natural,a.rural);urbanPaid=Math.min(need-rural,a.urban);a.rural-=ruralPaid;a.urban-=urbanPaid;}else{const paid=Math.min(need-natural,a.pooled);a.pooled-=paid;urbanPaid=Math.min(paid,need-rural);ruralPaid=paid-urbanPaid;}
    rows.push({goodId:n.goodId,need:need-natural-ruralPaid-urbanPaid,ruralNeed:rural-natural-ruralPaid,urbanNeed:need-rural-urbanPaid,usage:n.usage,needState:state});
  }return rows;
}

module.exports={enable,context,stock,validate,pending,demands,opening,ownership,validateOwnership,takeSector,incomingSector};
