// Finite synthetic land, separate from population, inventories and capital.
const {add,mul,number}=require('./autonomous-economy.cjs');
const methods=[{recipeId:'grow-grain',landPerBatch:10},{recipeId:'grow-fiber',landPerBatch:10}];
const sectorKeys=['ruralPopulation','urbanPopulation','ruralNeed','urbanNeed','ruralNatural','ruralAffordable','urbanAffordable','ruralPaid','urbanPaid','ruralSpending','urbanSpending','internalQuantity','internalPayment','internalCogs'];
const emptySectors=()=>Object.fromEntries(sectorKeys.map(k=>[k,0]));
function enable(state,hierarchy){
  const e=state.systems.economy;if(!e?.householdEconomy)return;
  if(!e.agriculture){const rural=new Map();for(const c of state.systems.population.cohorts)if(c.settlement==='rural')rural.set(c.territoryId,add(rural.get(c.territoryId)||0,c.count));const territory=new Map(hierarchy.territories.map(t=>[t.id,t]));
    e.agriculture={version:1,methods:methods.filter(m=>e.recipes.some(r=>r.id===m.recipeId)).map(m=>({...m})),rows:e.households.map(h=>{const area=territory.get(h.provinceId)?.areaKm2,geographic=Number.isFinite(area)&&area>=0,potentialLand=geographic?Math.floor(area*10):mul(Math.ceil((rural.get(h.provinceId)||0)/100),10);return {provinceId:h.provinceId,source:geographic?'synthetic-area':'synthetic-opening-rural',potentialLand,cultivatedLand:potentialLand,efficiencyBps:10000,usedLand:0,formalLand:0,householdLand:0};})};}
  // Migration introduces neither cash nor goods, and does not rewrite past ledgers.
  for(const row of e.householdEconomy.rows)if(!row.sectors)row.sectors=emptySectors();
}
function validate(e){
  const a=e.agriculture;if(!Object.hasOwn(e,'agriculture'))return;const safe=n=>Number.isSafeInteger(n)&&n>=0,fields=(o,keys)=>{if(!o||Object.getPrototypeOf(o)!==Object.prototype||Object.keys(o).length!==keys.length||keys.some(k=>!Object.hasOwn(o,k)))throw Error('Agriculture: invalid fields');};
  fields(a,['version','methods','rows']);if(a.version!==1||!e.householdEconomy||!Array.isArray(a.methods)||!Array.isArray(a.rows))throw Error('Agriculture: invalid version');let seen=new Set();for(const m of a.methods){fields(m,['recipeId','landPerBatch']);if(seen.has(m.recipeId)||!e.recipes.some(r=>r.id===m.recipeId)||!safe(m.landPerBatch)||!m.landPerBatch)throw Error('Agriculture: invalid method');seen.add(m.recipeId);}seen=new Set();const ids=new Set(e.households.map(h=>h.provinceId));for(const r of a.rows){fields(r,['provinceId','source','potentialLand','cultivatedLand','efficiencyBps','usedLand','formalLand','householdLand']);if(!ids.has(r.provinceId)||seen.has(r.provinceId)||!['synthetic-area','synthetic-opening-rural','authored'].includes(r.source)||Object.entries(r).some(([k,v])=>!['provinceId','source'].includes(k)&&!safe(v))||!r.efficiencyBps||r.cultivatedLand>r.potentialLand||r.usedLand>r.cultivatedLand||add(r.formalLand,r.householdLand)!==r.usedLand)throw Error('Agriculture: invalid land');seen.add(r.provinceId);}if(seen.size!==ids.size)throw Error('Agriculture: missing province');
}
// Scoped membership indexes hold live rows, never cached quantities or balances.
function context(e){return {land:new Map((e.agriculture?.rows||[]).map(r=>[r.provinceId,r])),methods:new Map((e.agriculture?.methods||[]).map(m=>[m.recipeId,m])),rows:new Map((e.householdEconomy?.rows||[]).map(r=>[r.householdId,r])),houses:new Map((e.households||[]).map(h=>[h.id,h])),recipes:new Map((e.recipes||[]).map(r=>[r.id,r])),needs:new Map((e.rules?.consumerNeeds||[]).map(n=>[n.id,n]))};}
function begin(e){for(const r of e.agriculture?.rows||[])r.usedLand=r.formalLand=r.householdLand=0;}
function limit(e,provinceId,recipeId,batches,household=false,index){const m=index?index.methods.get(recipeId):e.agriculture?.methods.find(m=>m.recipeId===recipeId);if(!m)return batches;const r=index?index.land.get(provinceId):e.agriculture.rows.find(r=>r.provinceId===provinceId),available=r.cultivatedLand-r.usedLand,allowed=Math.min(batches,number(BigInt(available)*BigInt(r.efficiencyBps)/(BigInt(m.landPerBatch)*10000n))),land=number((BigInt(allowed)*BigInt(m.landPerBatch)*10000n+BigInt(r.efficiencyBps)-1n)/BigInt(r.efficiencyBps));r.usedLand=add(r.usedLand,land);const key=household?'householdLand':'formalLand';r[key]=add(r[key],land);return allowed;}
function ruralNeed(e,h,need,index){const s=(index?index.rows.get(h.id):e.householdEconomy?.rows.find(r=>r.householdId===h.id))?.sectors;return s?number(BigInt(need)*BigInt(s.ruralPopulation)/BigInt(Math.max(1,add(s.ruralPopulation,s.urbanPopulation)))):need;}
function foodNeed(e,h,index){return h.consumerState.filter(s=>(index?index.needs.get(s.needId):e.rules.consumerNeeds.find(n=>n.id===s.needId)).goodId===e.rules.foodGoodId).reduce((n,s)=>add(n,s.stats.need),0);}
function reserves(e,row,index){const h=index?index.houses.get(row.householdId):e.households.find(h=>h.id===row.householdId),food=ruralNeed(e,h,foodNeed(e,h,index),index),result=new Map([[e.rules.foodGoodId,food]]);for(const stage of row.stages){const r=index?index.recipes.get(stage.recipeId):e.recipes.find(r=>r.id===stage.recipeId);for(const input of r.inputs)result.set(input.goodId,add(result.get(input.goodId)||0,mul(Math.min(stage.capacityBatches,Math.ceil(food/r.output.quantity)),input.quantity)));}return result;}
module.exports={enable,validate,context,begin,limit,ruralNeed,foodNeed,reserves,sectorKeys,emptySectors};
